-- Care Chart week-by-week content, First trimester (weeks 1-13).
-- Replaces First trimester's older, simpler locked format with the same
-- fuller card structure as Second trimester (migration_34): theme, mantra,
-- priority, journey, what-you-may-notice, Move (5/15/30-min tiers), Nourish,
-- Hydration goal, Reset (5-mood-mapped), Care for yourself, Your corner,
-- Support moment, Celebrate this week, For your care team.
--
-- Content: Roop's "First Trimester -- Final Move and Reset Edition" review
-- pass, 2026-07-29 -- her own reviewed content throughout, parsed
-- programmatically from the docx (not hand-transcribed) and round-trip
-- validated through the same JSON-escaping path the SQL generator uses,
-- zero errors across all 26 move/reset jsonb blocks.
--
-- Weeks 1-4 are intentionally identical (inserted as four duplicate rows,
-- one per week_number) -- the doc's own editorial note: "there is little
-- clinically useful week-to-week self-care distinction before most people
-- know they are pregnant" and explicitly instructs not to manufacture four
-- near-identical entries. Duplicating the one real entry across four rows
-- (rather than changing the schema to support week ranges) keeps the
-- existing exact-week_number lookup in dashboard/care/chart/page.tsx
-- working unchanged.

insert into care_chart_week_content
  (week_number, trimester, theme_title, mantra, priority, journey, what_you_may_notice, move, nourish, hydration_goal, reset, care_for_yourself, your_corner, support_moment, celebrate_this_week, for_your_care_team)
values
  (1, 'first', 'The quiet beginning', 'You do not have to feel different yet for this to be real.', 'Begin the few early habits that matter — without trying to feel pregnant.', 'By standard due-date counting, the first two weeks occur before conception. Fertilisation and implantation may happen later in this grouped period. Many people have no symptoms, and symptoms do not reliably predict pregnancy health.', ARRAY['No noticeable changes','Mild cramping or light spotting around implantation — or neither','Breast tenderness, tiredness or bloating','A missed period near the end of this stage']::text[], '{"focus": "Continue movement that already feels familiar; this is not the time to prove or suddenly transform fitness.", "tiers": {"heavy": "Walk gently for 3 minutes, then roll your shoulders and circle your ankles for 2 minutes.", "steady": "Take a 10-minute conversational walk, then spend 5 minutes on calf stretches, shoulder rolls and easy side-to-side weight shifts.", "feeling_good": "Choose 20 minutes of familiar moderate activity, then complete one easy round of 8 chair sit-to-stands, 8 wall push-ups and 10 heel raises."}, "mood_adjustment": "Uncertain or newly testing: choose familiar movement. Crampy or tired: use five minutes or rest. Feeling normal and well: continue your usual moderate option without overheating.", "safety": "Use stable support, breathe continuously and keep effort conversational. Stop for pain, bleeding, dizziness, chest pain, breathlessness before exertion, fluid leakage, calf pain/swelling or anything that feels wrong."}'::jsonb, 'If pregnancy is possible, take a prenatal vitamin containing folic acid as advised locally. Build meals from familiar foods; perfection is neither necessary nor possible.', 'Keep water nearby and drink regularly. Hydration needs vary with climate, activity and health conditions.', '{"heavy_day": "If uncertainty feels overwhelming, narrow the day to the next hour. Eat, drink, rest or contact someone safe — whichever need comes first.", "a_little_low": "Say: \"Not knowing yet is uncomfortable, and I do not have to solve it all today.\" Step away from repeated searching for ten minutes.", "okay": "Write down the date you plan to test or contact your clinician. Once the next step is clear, return to ordinary life.", "good": "Use the steadier mood to prepare one supportive habit: a vitamin reminder, an easy breakfast or a saved clinic number.", "really_good": "Let hope exist without demanding certainty. Record one sentence about how this beginning feels and keep it private if you prefer."}'::jsonb, 'Use a simple skin routine and check medicines, supplements or strong skincare actives with a qualified clinician or pharmacist rather than stopping prescribed treatment on your own.', 'Save one small memory from this beginning — a date, a photo, a private thought or nothing at all.', 'If you are sharing the possibility with someone, tell them what support would help: calm company, practical help or simply privacy.', 'Every pregnancy begins quietly. You do not need symptoms or certainty to deserve care.', 'Seek urgent care for severe or one-sided pain, shoulder-tip pain, fainting, heavy bleeding, fever or feeling seriously unwell.'),
  (2, 'first', 'The quiet beginning', 'You do not have to feel different yet for this to be real.', 'Begin the few early habits that matter — without trying to feel pregnant.', 'By standard due-date counting, the first two weeks occur before conception. Fertilisation and implantation may happen later in this grouped period. Many people have no symptoms, and symptoms do not reliably predict pregnancy health.', ARRAY['No noticeable changes','Mild cramping or light spotting around implantation — or neither','Breast tenderness, tiredness or bloating','A missed period near the end of this stage']::text[], '{"focus": "Continue movement that already feels familiar; this is not the time to prove or suddenly transform fitness.", "tiers": {"heavy": "Walk gently for 3 minutes, then roll your shoulders and circle your ankles for 2 minutes.", "steady": "Take a 10-minute conversational walk, then spend 5 minutes on calf stretches, shoulder rolls and easy side-to-side weight shifts.", "feeling_good": "Choose 20 minutes of familiar moderate activity, then complete one easy round of 8 chair sit-to-stands, 8 wall push-ups and 10 heel raises."}, "mood_adjustment": "Uncertain or newly testing: choose familiar movement. Crampy or tired: use five minutes or rest. Feeling normal and well: continue your usual moderate option without overheating.", "safety": "Use stable support, breathe continuously and keep effort conversational. Stop for pain, bleeding, dizziness, chest pain, breathlessness before exertion, fluid leakage, calf pain/swelling or anything that feels wrong."}'::jsonb, 'If pregnancy is possible, take a prenatal vitamin containing folic acid as advised locally. Build meals from familiar foods; perfection is neither necessary nor possible.', 'Keep water nearby and drink regularly. Hydration needs vary with climate, activity and health conditions.', '{"heavy_day": "If uncertainty feels overwhelming, narrow the day to the next hour. Eat, drink, rest or contact someone safe — which